import {test} from 'node:test';
import assert from 'node:assert/strict';
import {computePrice} from './price.ts';
test('default discount', () => assert.equal(computePrice(50), 45));
test('explicit discount', () => assert.equal(computePrice(100, 20), 80));
test('zero discount', () => assert.equal(computePrice(50, 0), 50));
test('fractional discount', () => assert.equal(computePrice(25, 0.25), 18.75));
test('zero percent discount should leave the price unchanged', () => assert.equal(computePrice(50, 0), 50));

